                c_b.left_child_count = n_left_count;
                c_b.right_child_node = n_right.clone();
                c_b.right_child_count = n_right_count;
            }

            if let Some(ref nl) = n_left {
                nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref nr) = n_right {
                nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            let mut current_bubble = bubble_start.clone();
            if !Rc::ptr_eq(&bubble_start, node) {
                while !Rc::ptr_eq(&current_bubble, &candidate) {
                    let left_depth = current_bubble.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let right_depth = current_bubble.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    current_bubble.borrow_mut().depth = imax(left_depth, right_depth);

