                if let Some(ref lc) = bu_b.left_child_node {
                    if Rc::ptr_eq(lc, &candidate) {
                        bu_b.left_child_count -= 1;
                    } else {
                        bu_b.right_child_count -= 1;
                    }
                } else {
                    bu_b.right_child_count -= 1;
                }
            }

        } else {
            let node_parent = node.borrow().parent_node.clone();
            if node_parent.is_none() {
                if let Some(ref lc) = left_child {
                    self.root_node = Some(lc.clone());
                    lc.borrow_mut().parent_node = None;
                } else if let Some(ref rc) = right_child {
                    self.root_node = Some(rc.clone());
                    rc.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let mut candidate = left_child.clone();
                let mut candidate_count = node.borrow().left_child_count;
                if right_child.is_some() {
                    candidate = right_child.clone();
                    candidate_count = node.borrow().right_child_count;
                }

                let p_weak = node_parent.as_ref().unwrap();
                let p = p_weak.upgrade().unwrap();
                {
                    let mut p_b = p.borrow_mut();
                    if let Some(ref lc) = p_b.left_child_node {
                        if Rc::ptr_eq(lc, node) {
                            p_b.left_child_node = candidate.clone();
                            p_b.left_child_count = candidate_count;
                        } else {
                            p_b.right_child_node = candidate.clone();
                            p_b.right_child_count = candidate_count;
                        }
                    } else {
                        p_b.right_child_node = candidate.clone();
                        p_b.right_child_count = candidate_count;
                    }
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = node_parent.clone();
                }

                bubble_up = Some(p);
            }
        }

        let mut bubbling_finished = false;
        let mut curr_bubble = bubble_up;
        while let Some(bu) = curr_bubble.clone() {
            if !bubbling_finished {
                let left_depth = bu.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let right_depth = bu.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let new_depth = imax(left_depth, right_depth);
                let depth_changed = new_depth != bu.borrow().depth;
                bu.borrow_mut().depth = new_depth;

                let balance = bostree_balance(&Some(bu.clone()));
                let mut rotated_bu = bu.clone();
                if balance < -1 {
                    let lc = bu.borrow().left_child_node.clone().unwrap();
                    if bostree_balance(&Some(lc.clone())) > 0 {
                        bostree_rotate_left(self, &lc);
                    }
                    rotated_bu = bostree_rotate_right(self, &bu);
                } else if balance > 1 {
                    let rc = bu.borrow().right_child_node.clone().unwrap();
                    if bostree_balance(&Some(rc.clone())) < 0 {
                        bostree_rotate_right(self, &rc);
                    }
                    rotated_bu = bostree_rotate_left(self, &bu);
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                }
                curr_bubble = Some(rotated_bu);
            }

            let p_weak = curr_bubble.as_ref().unwrap().borrow().parent_node.clone();
            if let Some(pw) = p_weak {
                let p = pw.upgrade().unwrap();
                {
                    let mut p_b = p.borrow_mut();
                    if let Some(ref lc) = p_b.left_child_node {
                        if Rc::ptr_eq(lc, curr_bubble.as_ref().unwrap()) {
                            p_b.left_child_count -= 1;
                        } else {
                            p_b.right_child_count -= 1;
                        }
                    } else {
                        p_b.right_child_count -= 1;
                    }
                }
                curr_bubble = Some(p);
            } else {
                curr_bubble = None;
            }
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let mut n_b = node.borrow_mut();
        n_b.weak_ref_count -= 1;
        if n_b.weak_ref_count == 0 {
            if let Some(free_fn) = self.free_function {
                drop(n_b);
                free_fn(node);
                return None;
            }
            None
        } else if n_b.weak_ref_node_valid != 0 {
            drop(n_b);
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current.clone() {
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node);
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
        None
    }

    pub fn bostree_select(&self, mut index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current.clone() {
            let l_count = node.borrow().left_child_count;
            if l_count <= index {
                index -= l_count;
                if index == 0 {
                    return Some(node);
                }
                index -= 1;
                current = node.borrow().right_child_node.clone();
            } else {
                current = node.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref right) = node.borrow().right_child_node {
        let mut curr = right.clone();
        loop {
            let left = curr.borrow().left_child_node.clone();
            if let Some(l) = left {
                curr = l;
            } else {
                break;
            }
        }
        return Some(curr);
    } else {
        let mut curr = node.clone();
        while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
            if let Some(parent) = parent_weak.upgrade() {
                let p_right = parent.borrow().right_child_node.clone();
                if let Some(pr) = p_right {
                    if Rc::ptr_eq(&pr, &curr) {
                        curr = parent;
                        continue;
                    }
                }
                return Some(parent);
            } else {
                break;
            }
        }
    }
    None
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref left) = node.borrow().left_child_node {
        let mut curr = left.clone();
        loop {
            let right = curr.borrow().right_child_node.clone();
            if let Some(r) = right {
                curr = r;
            } else {
                break;
            }
        }
        return Some(curr);
    } else {
        let mut curr = node.clone();
        while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
            if let Some(parent) = parent_weak.upgrade() {
                let p_left = parent.borrow().left_child_node.clone();
                if let Some(pl) = p_left {
                    if Rc::ptr_eq(&pl, &curr) {
                        curr = parent;
                        continue;
                    }
                }
                return Some(parent);
            } else {
                break;
            }
        }
    }
    None
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut curr = node.clone();

    while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
        if let Some(parent) = parent_weak.upgrade() {
            let p_right = parent.borrow().right_child_node.clone();
            if let Some(pr) = p_right {
                if Rc::ptr_eq(&pr, &curr) {
                    counter += 1 + parent.borrow().left_child_count;
                }
            }
            curr = parent;
        } else {
            break;
        }
    }
    counter
}
