use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

fn imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 { i1 } else { i2 }
}

fn bostree_balance(node_opt: &Option<Rc<RefCell<BOSNode>>>) -> i32 {
    if let Some(node) = node_opt {
        let node_b = node.borrow();
        let left_depth = node_b.left_child_node.as_ref().map_or(0, |l| l.borrow().depth + 1);
        let right_depth = node_b.right_child_node.as_ref().map_or(0, |r| r.borrow().depth + 1);
        (right_depth as i32) - (left_depth as i32)
    } else {
        0
    }
}

fn bostree_rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l = p.borrow().left_child_node.clone().unwrap();

    let p_parent = p.borrow().parent_node.clone();
    if let Some(ref parent_weak) = p_parent {
        if let Some(parent) = parent_weak.upgrade() {
            let mut pb = parent.borrow_mut();
            if let Some(ref lc) = pb.left_child_node {
                if Rc::ptr_eq(lc, p) {
                    pb.left_child_node = Some(l.clone());
                } else {
                    pb.right_child_node = Some(l.clone());
                }
            } else {
                pb.right_child_node = Some(l.clone());
            }
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    l.borrow_mut().parent_node = p_parent;

    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;

    {
        let mut pb = p.borrow_mut();
        pb.left_child_node = l_right.clone();
        pb.left_child_count = l_right_count;
        if let Some(ref lr) = l_right {
            lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }

        let p_left_depth = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let p_right_depth = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        pb.depth = imax(p_left_depth, p_right_depth);
        pb.parent_node = Some(Rc::downgrade(&l));
    }

    {
        let mut lb = l.borrow_mut();
        let p_left_count = p.borrow().left_child_count;
        let p_right_count = p.borrow().right_child_count;
        lb.right_child_node = Some(p.clone());
        lb.right_child_count = p_left_count + p_right_count + 1;

        let l_left_depth = lb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let l_right_depth = lb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        lb.depth = imax(l_left_depth, l_right_depth);
    }

    l
}

fn bostree_rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let r = p.borrow().right_child_node.clone().unwrap();

    let p_parent = p.borrow().parent_node.clone();
    if let Some(ref parent_weak) = p_parent {
        if let Some(parent) = parent_weak.upgrade() {
            let mut pb = parent.borrow_mut();
            if let Some(ref lc) = pb.left_child_node {
                if Rc::ptr_eq(lc, p) {
                    pb.left_child_node = Some(r.clone());
                } else {
                    pb.right_child_node = Some(r.clone());
                }
            } else {
                pb.right_child_node = Some(r.clone());
            }
        }
    } else {
        tree.root_node = Some(r.clone());
    }

    r.borrow_mut().parent_node = p_parent;

    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;

    {
        let mut pb = p.borrow_mut();
        pb.right_child_node = r_left.clone();
        pb.right_child_count = r_left_count;
        if let Some(ref rl) = r_left {
            rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }

        let p_left_depth = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let p_right_depth = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        pb.depth = imax(p_left_depth, p_right_depth);
        pb.parent_node = Some(Rc::downgrade(&r));
    }

    {
        let mut rb = r.borrow_mut();
        let p_left_count = p.borrow().left_child_count;
        let p_right_count = p.borrow().right_child_count;
        rb.left_child_node = Some(p.clone());
        rb.left_child_count = p_left_count + p_right_count + 1;

        let r_left_depth = rb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let r_right_depth = rb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        rb.depth = imax(r_left_depth, r_right_depth);
    }

    r
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        Self {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        if let Some(ref root) = self.root_node {
            root.borrow().left_child_count + root.borrow().right_child_count + 1
        } else {
            0
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let mut current = self.root_node.clone();
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;
        let mut is_left = false;

        while let Some(node) = current.clone() {
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                current = node.borrow().left_child_node.clone();
                is_left = true;
            } else {
                node.borrow_mut().right_child_count += 1;
                current = node.borrow().right_child_node.clone();
                is_left = false;
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(Rc::downgrade),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        if let Some(parent) = parent_node.clone() {
            if is_left {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }

            let p_has_left = parent.borrow().left_child_node.is_some();
            let p_has_right = parent.borrow().right_child_node.is_some();

            if p_has_left ^ p_has_right {
                parent.borrow_mut().depth += 1;
                let mut curr_p = parent.clone();
                while let Some(parent_parent_weak) = curr_p.clone().borrow().parent_node.clone() {
                    let parent_parent = parent_parent_weak.upgrade().unwrap();
                    curr_p = parent_parent.clone();

                    let new_left_depth = curr_p.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let new_right_depth = curr_p.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);

                    let max_depth = imax(new_left_depth, new_right_depth);

                    if curr_p.borrow().depth != max_depth {
                        curr_p.borrow_mut().depth = max_depth;
                    } else {
                        break;
                    }

                    if new_left_depth >= 2 && new_left_depth - 2 == new_right_depth {
                        let lc = curr_p.borrow().left_child_node.clone().unwrap();
                        if bostree_balance(&Some(lc.clone())) > 0 {
                            bostree_rotate_left(self, &lc);
                        }
                        curr_p = bostree_rotate_right(self, &curr_p);
                    } else if new_left_depth + 2 == new_right_depth {
                        let rc = curr_p.borrow().right_child_node.clone().unwrap();
                        if bostree_balance(&Some(rc.clone())) < 0 {
                            bostree_rotate_right(self, &rc);
                        }
                        curr_p = bostree_rotate_left(self, &curr_p);
                    }
                }
            }
        } else {
            self.root_node = Some(new_node.clone());
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let mut bubble_up: Option<Rc<RefCell<BOSNode>>> = None;

        let left_child = node.borrow().left_child_node.clone();
        let right_child = node.borrow().right_child_node.clone();

        if left_child.is_some() && right_child.is_some() {
            let left_c = left_child.unwrap();
            let right_c = right_child.unwrap();

            let mut candidate: Rc<RefCell<BOSNode>>;
            let mut lost_child: Option<Rc<RefCell<BOSNode>>>;

            if left_c.borrow().depth >= right_c.borrow().depth {
                node.borrow_mut().left_child_count -= 1;
                candidate = left_c;
                while candidate.borrow().right_child_node.is_some() {
                    candidate.borrow_mut().right_child_count -= 1;
                    let next = candidate.borrow().right_child_node.clone().unwrap();
                    candidate = next;
                }
                lost_child = candidate.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count -= 1;
                candidate = right_c;
                while candidate.borrow().left_child_node.is_some() {
                    candidate.borrow_mut().left_child_count -= 1;
                    let next = candidate.borrow().left_child_node.clone().unwrap();
                    candidate = next;
                }
                lost_child = candidate.borrow().right_child_node.clone();
            }

            let bubble_start = candidate.borrow().parent_node.clone().unwrap().upgrade().unwrap();

            {
                let mut bs_b = bubble_start.borrow_mut();
                if let Some(ref lc) = bs_b.left_child_node {
                    if Rc::ptr_eq(lc, &candidate) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                } else {
                    bs_b.right_child_node = lost_child.clone();
                }
            }
            if let Some(ref lc) = lost_child {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
            }

            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref p_weak) = node_parent {
                if let Some(p) = p_weak.upgrade() {
                    let mut p_b = p.borrow_mut();
                    if let Some(ref lc) = p_b.left_child_node {
                        if Rc::ptr_eq(lc, node) {
                            p_b.left_child_node = Some(candidate.clone());
                        } else {
                            p_b.right_child_node = Some(candidate.clone());
                        }
                    } else {
                        p_b.right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node_parent;

            let n_left = node.borrow().left_child_node.clone();
            let n_left_count = node.borrow().left_child_count;
            let n_right = node.borrow().right_child_node.clone();
            let n_right_count = node.borrow().right_child_count;

            {
                let mut c_b = candidate.borrow_mut();
                c_b.left_child_node = n_left.clone();
                c_b.left_child_count = n_left_count;
                c_b.right_child_node = n_right.clone();
                c_b.right_child_count = n_right_count;
            }

            if let Some(ref nl) = n_left {
                nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref nr) = n_right {
                nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            let mut current_bubble = bubble_start.clone();
            if !Rc::ptr_eq(&bubble_start, node) {
                while !Rc::ptr_eq(&current_bubble, &candidate) {
                    let left_depth = current_bubble.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let right_depth = current_bubble.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    current_bubble.borrow_mut().depth = imax(left_depth, right_depth);

                    let balance = bostree_balance(&Some(current_bubble.clone()));
                    if balance > 1 {
                        let rc = current_bubble.borrow().right_child_node.clone().unwrap();
                        if bostree_balance(&Some(rc.clone())) < 0 {
                            bostree_rotate_right(self, &rc);
                        }
                        current_bubble = bostree_rotate_left(self, &current_bubble);
                    } else if balance < -1 {
                        let lc = current_bubble.borrow().left_child_node.clone().unwrap();
                        if bostree_balance(&Some(lc.clone())) > 0 {
                            bostree_rotate_left(self, &lc);
                        }
                        current_bubble = bostree_rotate_right(self, &current_bubble);
                    }

                    let next = current_bubble.borrow().parent_node.clone().unwrap().upgrade().unwrap();
                    current_bubble = next;
                }
            }

            let c_left_depth = candidate.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
            let c_right_depth = candidate.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
            candidate.borrow_mut().depth = imax(c_left_depth, c_right_depth);

            bubble_up = candidate.borrow().parent_node.clone().map(|w| w.upgrade().unwrap());

            if let Some(ref bu) = bubble_up {
                let mut bu_b = bu.borrow_mut();
                if let Some(ref lc) = bu_b.left_child_node {
                    if Rc::ptr_eq(lc, &candidate) {
                        bu_b.left_child_count -= 1;
                    } else {
                        bu_b.right_child_count -= 1;
                    }
                } else {
                    bu_b.right_child_count -= 1;
                }
            }

        } else {
            let node_parent = node.borrow().parent_node.clone();
            if node_parent.is_none() {
                if let Some(ref lc) = left_child {
                    self.root_node = Some(lc.clone());
