pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref right) = node.borrow().right_child_node {
        let mut curr = right.clone();
        loop {
            let left = curr.borrow().left_child_node.clone();
            if let Some(l) = left {
                curr = l;
            } else {
                break;
            }
        }
        return Some(curr);
    } else {
        let mut curr = node.clone();
        while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
            if let Some(parent) = parent_weak.upgrade() {
                let p_right = parent.borrow().right_child_node.clone();
                if let Some(pr) = p_right {
                    if Rc::ptr_eq(&pr, &curr) {
                        curr = parent;
                        continue;
                    }
                }
                return Some(parent);
            } else {
                break;
            }
        }
    }
    None
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref left) = node.borrow().left_child_node {
        let mut curr = left.clone();
        loop {
            let right = curr.borrow().right_child_node.clone();
            if let Some(r) = right {
                curr = r;
            } else {
                break;
            }
        }
        return Some(curr);
    } else {
        let mut curr = node.clone();
        while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
            if let Some(parent) = parent_weak.upgrade() {
                let p_left = parent.borrow().left_child_node.clone();
                if let Some(pl) = p_left {
                    if Rc::ptr_eq(&pl, &curr) {
                        curr = parent;
                        continue;
                    }
                }
                return Some(parent);
            } else {
                break;
            }
        }
    }
    None
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut curr = node.clone();

    while let Some(parent_weak) = curr.clone().borrow().parent_node.clone() {
        if let Some(parent) = parent_weak.upgrade() {
            let p_right = parent.borrow().right_child_node.clone();
            if let Some(pr) = p_right {
                if Rc::ptr_eq(&pr, &curr) {
                    counter += 1 + parent.borrow().left_child_count;
                }
            }
            curr = parent;
        } else {
            break;
        }
    }
    counter
